# Test Case 1: p^e = 3e + 1 for p >= 3 odd prime

def check_solutions(p, e):
    return p**e == 3*e + 1

print("Testing p=3:")
for e in range(1, 10):
    print(f"e={e}: 3^{e} vs 3*{e}+1. Match: {check_solutions(3, e)}")

print("\nTesting p=5:")
for e in range(1, 6):
    print(f"e={e}: 5^{e} vs 3*{e}+1. Match: {check_solutions(5, e)}")

